namespace fs=std::filesystem;
static constexpr unsigned short PORT=8765;
static std::string AdminPage(){return R"HTML(<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>PCPM — Реклама</title><style>body{font:16px Segoe UI,Arial;background:#101a2c;color:#e8f1ff;max-width:900px;margin:35px auto;padding:0 20px}textarea,input{width:100%;box-sizing:border-box;background:#192943;color:white;border:1px solid #52708f;padding:10px;margin:7px 0}textarea{height:180px}button{background:#167ca8;color:white;border:0;padding:11px 18px;margin:8px 5px 8px 0;cursor:pointer}small{color:#9eb5cc}img{max-width:320px;max-height:120px;display:block;margin:10px 0}</style><h1>Управление рекламой</h1><h3>Загрузка графического баннера</h3><input id="file" type="file" accept=".png,.jpg,.jpeg,image/png,image/jpeg"><button onclick="upload()">Загрузить изображение</button><img id="preview"><p id="fileStatus"></p><h3>Рекламные объявления</h3><p>Формат строки: <b>Заголовок|URL рекламодателя|интервал_секунд|имя_файла</b>. Имя файла — результат загрузки выше; можно оставить пустым.</p><textarea id="data" spellcheck="false"></textarea><br><button onclick="save()">Сохранить изменения</button><button onclick="load()">Обновить</button><p id="status"></p><small>Допускаются только PNG/JPEG до 2 МБ. Сервер доступен только на этом компьютере через 127.0.0.1.</small><script>let uploaded='';document.querySelector('#file').onchange=e=>{let f=e.target.files[0];if(f)document.querySelector('#preview').src=URL.createObjectURL(f)};async function upload(){let f=document.querySelector('#file').files[0];if(!f)return alert('Выберите PNG или JPEG');let ext=f.name.toLowerCase().endsWith('.png')?'png':(f.name.toLowerCase().match(/\.jpe?g$/)?'jpg':'');if(!ext)return alert('Допускаются PNG/JPG');let name='banner_'+Date.now()+'.'+ext;let r=await fetch('/api/image/'+name,{method:'POST',headers:{'Content-Type':f.type},body:f});if(!r.ok){document.querySelector('#fileStatus').textContent='Ошибка загрузки';return}uploaded=name;document.querySelector('#fileStatus').textContent='Загружено: '+name;document.querySelector('#data').value += (document.querySelector('#data').value.trim()?'\n':'')+'Новый баннер|https://example.com|10|'+name;}async function load(){let r=await fetch('/api/banners.tsv');document.querySelector('#data').value=await r.text();document.querySelector('#status').textContent='Загружено'}async function save(){let r=await fetch('/api/banners.tsv',{method:'POST',headers:{'Content-Type':'text/plain; charset=utf-8'},body:document.querySelector('#data').value});document.querySelector('#status').textContent=r.ok?'Сохранено':'Ошибка: '+await r.text()}load();</script></html>)HTML";}
static std::string Read(const fs::path&p){std::ifstream f(p,std::ios::binary);return f?std::string((std::istreambuf_iterator<char>(f)),{}):std::string{};}
static void Send(SOCKET s,int code,const char*type,const std::string&body){std::ostringstream h;h<<"HTTP/1.1 "<<code<<(code==200?" OK":code==400?" Bad Request":code==404?" Not Found":code==413?" Payload Too Large":" Error")<<"\r\nContent-Type: "<<type<<"\r\nContent-Length: "<<body.size()<<"\r\nConnection: close\r\nCache-Control: no-store\r\nX-Content-Type-Options: nosniff\r\n\r\n";auto x=h.str()+body;size_t off=0;while(off<x.size()){int n=send(s,x.data()+off,(int)std::min<size_t>(x.size()-off,1<<20),0);if(n<=0)break;off+=n;}}
static bool SafeName(const std::string&n){if(n.empty()||n.size()>80||n.find("..")!=std::string::npos)return false;for(char c:n)if(!((c>='a'&&c<='z')||(c>='A'&&c<='Z')||(c>='0'&&c<='9')||c=='_'||c=='-'||c=='.'))return false;auto dot=n.find_last_of('.');if(dot==std::string::npos)return false;auto ext=n.substr(dot);std::transform(ext.begin(),ext.end(),ext.begin(),::tolower);return ext==".png"||ext==".jpg"||ext==".jpeg";}
int main(){WSADATA w{};if(WSAStartup(MAKEWORD(2,2),&w))return 1;SOCKET srv=socket(AF_INET,SOCK_STREAM,IPPROTO_TCP);if(srv==INVALID_SOCKET)return 2;sockaddr_in a{};a.sin_family=AF_INET;a.sin_port=htons(PORT);InetPtonA(AF_INET,"127.0.0.1",&a.sin_addr);if(bind(srv,(sockaddr*)&a,sizeof(a))==SOCKET_ERROR||listen(srv,8)==SOCKET_ERROR){closesocket(srv);WSACleanup();return 3;}
 fs::path dir=fs::path(getenv("LOCALAPPDATA")?getenv("LOCALAPPDATA"):".")/"PCPerformanceMonitor"/"ads";fs::create_directories(dir);fs::path manifest=dir/"banners.tsv";if(!fs::exists(manifest)){std::ofstream f(manifest);f<<"Пример рекламного баннера|https://example.com|10|\n";}std::cout<<"Admin: http://127.0.0.1:"<<PORT<<"/admin\n";
 for(;;){SOCKET c=accept(srv,nullptr,nullptr);if(c==INVALID_SOCKET)continue;std::string req;char b[8192];size_t headerEnd=std::string::npos,bodyLen=0;int n;while((n=recv(c,b,sizeof(b),0))>0){req.append(b,n);headerEnd=req.find("\r\n\r\n");if(headerEnd!=std::string::npos){auto cl=req.find("Content-Length:");if(cl!=std::string::npos){cl+=15;while(cl<req.size()&&req[cl]==' ')++cl;try{bodyLen=std::stoul(req.substr(cl));}catch(...){bodyLen=0;}}if(req.size()>=headerEnd+4+bodyLen)break;}if(req.size()>3*1024*1024)break;}
 std::string first=req.substr(0,req.find("\r\n")),body=headerEnd==std::string::npos?"":req.substr(headerEnd+4);auto sp=first.find(' '),ep=first.find(' ',sp+1);std::string method=first.substr(0,sp),path=first.substr(sp+1,ep-sp-1);
 if(method=="GET"&&path=="/admin")Send(c,200,"text/html; charset=utf-8",AdminPage());
 else if(method=="GET"&&path=="/api/banners.tsv")Send(c,200,"text/plain; charset=utf-8",Read(manifest));
 else if(method=="GET"&&path.rfind("/api/image/",0)==0){std::string name=path.substr(11);if(!SafeName(name))Send(c,400,"text/plain","Bad filename");else{auto ext=fs::path(name).extension().string();std::transform(ext.begin(),ext.end(),ext.begin(),::tolower);Send(c,200,ext==".png"?"image/png":"image/jpeg",Read(dir/name));}}
 else if(method=="POST"&&path=="/api/banners.tsv"){if(body.size()>65536)Send(c,413,"text/plain","Too large");else{bool valid=true;std::istringstream in(body);std::string line;while(std::getline(in,line)){if(line.empty())continue;auto p=line.find('|'),q=line.find('|',p+1),z=line.find('|',q+1);if(p==std::string::npos||q==std::string::npos){valid=false;break;}auto url=line.substr(p+1,q-p-1);if(url.rfind("https://",0)!=0&&url.rfind("http://",0)!=0){valid=false;break;}if(z!=std::string::npos){auto image=line.substr(z+1);if(!image.empty()&&!SafeName(image)){valid=false;break;}}}if(valid){std::ofstream f(manifest,std::ios::binary|std::ios::trunc);f<<body;Send(c,200,"text/plain","Saved");}else Send(c,400,"text/plain","Invalid entry");}}
 else if(method=="POST"&&path.rfind("/api/image/",0)==0){std::string name=path.substr(11);bool png=body.size()>=8&&(unsigned char)body[0]==0x89&&body.substr(1,3)=="PNG";bool jpg=body.size()>=3&&(unsigned char)body[0]==0xff&&(unsigned char)body[1]==0xd8&&(unsigned char)body[2]==0xff;if(!SafeName(name)||body.size()>2*1024*1024||body.empty()||(!png&&!jpg))Send(c,400,"text/plain","Only valid PNG/JPEG up to 2 MB");else{std::ofstream f(dir/name,std::ios::binary|std::ios::trunc);f.write(body.data(),body.size());Send(c,200,"text/plain","Uploaded");}}
 else Send(c,404,"text/plain","Not found");shutdown(c,SD_BOTH);closesocket(c);}
}